export function collectionTicksRequest(ids,rawTicks,next){
  if(!Array.isArray(ids)||ids.length<1||ids.length>128||new Set(ids).size!==ids.length)fail('Select 1..128 unique ItemIds');
  const changes=ids.map(itemId=>{const expected=rawTicks.get(itemId);if(!Number.isInteger(itemId)||typeof expected!=='string'||! /^(?:0|-?[1-9][0-9]*)$/.test(expected)||expected===next)fail('Missing/unchanged history tick');return {itemId,expected,next};});return {operation:'collection-key1-ticks',changes};
}
export function nativeOutputStatus(){return Object.freeze({apply:false,export:false,reason:'NATIVE_OUTPUT_NOT_INDEPENDENTLY_ACCEPTED'});}

export function achievementBatchRequest(keys,operation,value){
  const progress=operation==='achievement-progress';
  if(!progress&&operation!=='achievement-timestamp')fail('UNSUPPORTED_ACHIEVEMENT_BATCH_OPERATION');
  const limit=progress?64:128;
  if(!Array.isArray(keys)||keys.length<1||keys.length>limit||keys.some(k=>typeof k!=='string'||!k.trim())||new Set(keys).size!==keys.length)fail(`絞り込み対象は重複のない1..${limit}件にしてください（128フィールド上限）`);
  if(typeof value!=='string'||!value.trim())fail('値を指定してください');
  if(progress&&(!/^(?:0|[1-9][0-9]*)(?:\.[0-9]+)?$/.test(value)||!Number.isFinite(Number(value))))fail('進捗は有限の非負数を指定してください');
  const edits=keys.map(key=>progress?{operation,key,progress:Number(value)}:{operation,key,completedAt:value});
  return edits.length===1?edits[0]:{operation:'batch-independent-scalars',edits};
}

export function recipeForwardRequest(row,consent){
  if(row?.itemId!==RECIPE_ITEM||row.quantity!==1||row.projectionOnly!==true||!Number.isSafeInteger(row.documentId)||row.documentId<0)fail('RECIPE_EXACT_EXISTING_ROW_REQUIRED');
  if(consent?.acknowledgeRecipeAvailabilityChange!==true||consent?.acknowledgeAchievementAndRewardReference!==true)fail('RECIPE_CONSENT_REQUIRED');
  return {operation:RECIPE_OPERATION,itemId:RECIPE_ITEM,documentId:row.documentId,expectedQuantity:1,nextQuantity:0,acknowledgeRecipeAvailabilityChange:true,acknowledgeAchievementAndRewardReference:true};
}

export function recipeExpansionForwardRequest(row,consent){
  if(!RECIPE_EXPANSION_IDS.includes(row?.itemId)||row.quantity!==1||!Number.isSafeInteger(row.documentId)||row.documentId<=0)fail('RECIPE_EXPANSION_EXACT_EXISTING_ROW_REQUIRED');
  if(consent?.acknowledgeRecipeAvailabilityChange!==true||consent?.acknowledgeAchievementAndRewardReference!==true)fail('RECIPE_CONSENT_REQUIRED');
  return {operation:RECIPE_EXPANSION_OPERATION,itemId:row.itemId,documentId:row.documentId,expectedQuantity:1,nextQuantity:0,acknowledgeRecipeAvailabilityChange:true,acknowledgeAchievementAndRewardReference:true};
}

export function bulkTargetReason(row,operation,capability){
  if(!capability?.allowedPreviewOperations?.includes(operation))return '操作Capability未対応';
  if(operation===FAMILY_BATCH_OPERATION){
    if(row.domain!=='achievement'||!row.saved||!FORMAL_FAMILY_REVOKE_KEYS.includes(row.key))return '限定Family対象外';
    if(row.familyReason)return row.familyReason;
    if(row.complete!==true)return '達成済み対象のみ';
    return null;
  }
  if(row.domain==='achievement'){
    if(!row.saved)return '未保存・状態UNKNOWN';
    if(!row.key)return 'GUID未照合';
    if(row.gated)return 'DLC・イベント条件付き（この操作は未対応）';
    if(row.group==='collection_puzzle')return 'Puzzle専用連動操作の対象';
    if(row.counterPresent===false)return '関連Counter未保存・未照合';
    if(operation==='achievement-timestamp'&&row.complete!==true)return '達成済みの既存日時のみ';
    if(operation==='achievement-progress'){
      if(row.complete!==false)return '未達成の進捗のみ（達成取消は別操作）';
      if(row.manual!==true)return '手動Scalar以外は未対応';
    }
    return null;
  }
  if(row.domain==='collection')return row.saved?null:'既存のKey1履歴なし（実取得・履歴追加は別操作）';
  return '対象未照合';
}
export function bulkSelectionSnapshot(rows,selected,operation,capability){
  const limits={'achievement-timestamp':128,'achievement-progress':64,'collection-key1-ticks':128,'batch-family-revoke':3};
  const limit=limits[operation]??0,byId=new Map();
  for(const row of rows){if(byId.has(row.id))fail('DUPLICATE_BULK_TARGET');byId.set(row.id,row);}
  if(!Array.isArray(selected)||new Set(selected).size!==selected.length)fail('DUPLICATE_BULK_SELECTION');
  const targets=selected.map(id=>{const row=byId.get(id);if(!row)fail('UNKNOWN_BULK_SELECTION');return row;});
  const blocked=targets.map(row=>({id:row.id,reason:bulkTargetReason(row,operation,capability)})).filter(r=>r.reason);
  const batchMissing=targets.length>1&&typeof operation==='string'&&operation.startsWith('achievement-')&&!capability?.allowedPreviewOperations?.includes('batch-independent-scalars');
  const reason=!limit?'未対応操作':!targets.length?'対象を選択してください':operation===FAMILY_BATCH_OPERATION&&targets.length<2?'Family一括取消は2〜3件を選択してください':targets.length>limit?`上限超過：${targets.length}/${limit}件。対象を減らしてください。`:blocked.length?`未対応対象 ${blocked.length}件。選択を解除してください。`:batchMissing?'原子的Batch Capability未対応':null;
  return {targets,blocked,limit,reason,ready:reason===null};
}

